from urllib.parse import quote
R=Path(__file__).resolve().parent; D=R/'docs'; data=json.loads((R/'content.json').read_text()); stores=data['stores']; categories=data['categories']; lineup=data['lineup']; photos=json.loads((R/'archive-v2.json').read_text()); ORIGIN='https://cmcnosky.github.io/ashes-smoke-shop-preview'
