def icon(kind):
 shapes={'leaf':'<path d="M32 54V29M32 42C10 43 10 20 10 20s22 0 22 22Zm0-9C53 32 54 10 54 10S32 11 32 33Z"/>','vape':'<rect x="13" y="24" width="16" height="32" rx="4"/><path d="M17 24V12h8v12M43 56V28h11v28ZM46 28v-9h5v9M19 40h4M45 42h7"/>','pipe':'<path d="M13 13h18v7h-3v18l9 13q3 7-4 7H12q-7 0-4-7l9-13V20h-4ZM15 45h16M32 40l13-13 8 7-14 14M43 24l12 12M18 13V6h8v7"/>','papers':'<path d="m8 25 40-12 8 28-40 12ZM8 25l8 28M14 29l34-10M23 39l23-7M21 45l28-8"/>','grinder':'<ellipse cx="32" cy="16" rx="23" ry="9"/><path d="M9 16v31c0 12 46 12 46 0V16M9 32c0 12 46 12 46 0M17 26v7M27 29v7M38 29v7M48 26v7M18 46v6M28 48v6M38 48v6M48 46v6"/>','hookah':'<path d="M18 7h14l-4 8h-6ZM25 15v20l-9 15q-4 9 9 9t9-9l-9-15M15 23h20M31 35q21-11 20 8t-9 10M51 43V25h5v-6M17 51h17"/>','plant':'<path d="M31 58V20M31 40C8 43 8 25 8 25s21-2 23 15Zm0-9c22 3 24-17 24-17s-23-2-24 17ZM31 20C15 13 31 3 31 3s15 10 0 17Z"/>','candle':'<path d="M14 27h36v29H14ZM14 35h36M32 27v-9M32 18c-12 0-6-15 0-16 0 8 10 16 0 16ZM23 44h18M23 49h13"/>'}
 return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+shapes[kind]+'</svg>'
def header(active):
 links=[('explore.html','Products','products'),('locations.html','Locations','locations'),('story.html','About','about'),('contact.html','Contact','contact')]
 return '<a class="skip" href="#main">Skip to content</a><div class="utility"><span>Independent spirit. North Texas roots.</span><span>Denton since 2014 <b>✦</b> Lewisville since 2023</span></div><header class="header"><a class="brand" href="index.html" aria-label="Ashes home">'+logo()+'''<span>SMOKE SHOP</span></a><nav id="main-nav" aria-label="Main navigation">'''+''.join(f'<a href="{url}"'+(' aria-current="page"' if active==key else '')+f'>{label}</a>' for url,label,key in links)+'''</nav><a class="header-visit" href="locations.html">Locations & hours <span aria-hidden="true">↗</span></a></header>'''
def footer():return '''<footer class="footer"><div class="footer-grid"><div class="footer-brand">'''+logo('cream')+'''<p>Smoke shop. Local soul.<br>Denton & Old Town Lewisville.</p></div><div><h2>Products</h2><a href="explore.html#hemp-cbd">Hemp & CBD</a><a href="explore.html#vapes">Vapes & e-liquid</a><a href="explore.html#glass">Glass & pipes</a><a href="explore.html">All product categories</a></div><div><h2>Locations & contact</h2><a href="denton.html">Denton · 11am–11pm</a><a href="tel:+19403811010">(940) 381-1010</a><a href="lewisville.html">Lewisville · 10am–10pm</a><a href="tel:+14699688008">(469) 968-8008</a><a href="contact.html">Contact the shops</a></div><div><h2>About & social</h2><a href="story.html">About Ashes</a><a href="archive.html">Photo archive</a><a href="https://www.instagram.com/ashes.tx/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.facebook.com/ashesdenton/" target="_blank" rel="noopener">Denton Facebook ↗</a><a href="https://www.facebook.com/asheslewisville/" target="_blank" rel="noopener">Lewisville Facebook ↗</a></div></div><div class="footer-bottom"><span>© Ashes Smoke Shop, LLC.</span><span>Website concept by <a href="https://cleargraindocs.com/">Cleargrain</a></span><a href="https://www.ashestx.com/" target="_blank" rel="noopener">Original website ↗</a></div></footer>'''
def page(name,title,desc,body,active=''):
 base=f'<base href="{ORIGIN}/">' if name=='404.html' else ''
 page_header=header(active).replace('href="#main"','href="404.html#main"') if name=='404.html' else header(active)
 (D/name).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">{base}<title>{e(title)} | Ashes</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#f6cb4e"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="{ORIGIN}/{name}"><meta property="og:title" content="{e(title)} | Ashes"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}/{name}"><meta property="og:image" content="{ORIGIN}/assets/social-preview-v4.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="assets/favicon-v4.png"><link rel="stylesheet" href="assets/fonts.css"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script></head><body>{page_header}<main id="main">{body}</main>{footer()}</body></html>''')
def shop(s,i,heading=3,detail=False):
 title=e(s['name']) if detail else f'<a href="{s["id"]}.html">{s["name"]}</a>'
 more='' if detail else f'<a class="small-link" href="{s["id"]}.html">Parking & store details →</a>'
 return f'''<article class="store-card {s['id']}" id="{s['id']}-contact"><div class="store-heading"><div><span class="eyebrow">{s['area']}</span><h{heading}>{title}</h{heading}></div><span class="store-spark" aria-hidden="true">✦</span></div><p class="address">{s['street']}<br>{s['city']}</p><div class="store-hours"><span>Open daily</span><strong>{s['hours']}</strong></div><a class="store-phone" href="tel:{s['tel']}">{s['phone']}</a><div class="store-actions"><a class="button dark" href="{maps(s)}" target="_blank" rel="noopener">Directions <span aria-hidden="true">↗</span></a><a class="button outline" href="tel:{s['tel']}">Call {s['name']}</a></div>{more}</article>'''
def shops(heading=3):return '<div class="store-grid">'+''.join(shop(s,i,heading) for i,s in enumerate(stores,1))+'</div><p class="small-note">Regular daily hours shown. Call the shop for holiday hours and today’s product availability.</p>'
def faq():return '''<section class="section faq-section" id="questions"><div><span class="eyebrow">BEFORE YOU VISIT</span><h2>Common questions</h2></div><div class="faq"><details><summary>What are your opening hours?<span>+</span></summary><p>Denton is open daily, 11am–11pm. Lewisville is open daily, 10am–10pm. Call for holiday or special hours.</p></details><details><summary>How do I check product availability?<span>+</span></summary><p>Call <a href="tel:+19403811010">Denton at (940) 381-1010</a> or <a href="tel:+14699688008">Lewisville at (469) 968-8008</a>. The <a href="explore.html">product guide</a> shows categories, rather than live stock.</p></details><details><summary>Where can I park?<span>+</span></summary><p>Denton has parking out front. Lewisville has nearby street parking and Old Town lots. Choose <a href="denton.html">Denton</a> or <a href="lewisville.html">Lewisville</a> for directions and parking details.</p></details><details><summary>Can I browse without buying?<span>+</span></summary><p>Yes. Take your time and ask questions. Ashes staff do not work on commission.</p></details></div></section>'''
