def category_links():return ''.join(f'<a class="category-card {color}" href="explore.html#{key}"><span class="category-icon">{icon(kind)}</span><span><strong>{name}</strong><small>{desc}</small></span><span class="category-arrow" aria-hidden="true">↗</span></a>' for key,name,desc,rows,color,kind in GROUPS)
home='''<section class="home-hero"><div class="hero-copy"><span class="eyebrow">ASHES SMOKE SHOP · DENTON & LEWISVILLE</span><h1>A smoke shop<br>with a little<br><em>more soul.</em></h1><p>Hemp & CBD, vapes, glass, papers and the everyday essentials. Good people. No pressure. Come find your thing.</p><div class="hero-actions"><a class="button dark" href="explore.html">Browse products <span aria-hidden="true">→</span></a><a class="button outline" href="locations.html">Locations & hours</a></div></div><figure class="hero-art"><img src="assets/ashes-v4-hero.webp" alt="Original Ashes illustration of a relaxed skeleton with a grinder, rolling papers and a pipe" width="1254" height="1254" fetchpriority="high"></figure></section><section class="section home-products" id="products"><div class="section-heading"><div><span class="eyebrow">FIND WHAT YOU CAME FOR</span><h2>Product categories</h2></div><a class="text-link" href="explore.html">View all products →</a></div><div class="category-grid">'''+category_links()+'''</div><p class="small-note">Explore our categories, then call or visit for today’s selection.</p></section><section class="section home-locations" id="locations"><div class="section-heading"><div><span class="eyebrow">TWO LOCATIONS. SAME ASHES SPIRIT.</span><h2>Visit a shop</h2></div><a class="text-link" href="locations.html">All location details →</a></div>'''+shops()+'''</section>'''+event()+'''<section class="about-band"><div class="about-doodle" aria-hidden="true">✦</div><div><span class="eyebrow">INDEPENDENT SPIRIT, SINCE 2014</span><h2>A little offbeat.<br>A lot like home.</h2></div><div><p>From South Carroll Boulevard to Old Town Lewisville, Ashes is a place to browse, ask questions and find something that feels like you.</p><a class="text-link" href="story.html">About Ashes →</a></div></section><section class="help-bar"><h2>Need a hand?</h2><a class="text-link" href="contact.html">Contact a shop →</a><a class="text-link" href="locations.html#questions">Visiting information & FAQs →</a></section>'''
