page('locations.html','Locations & Hours','Addresses, daily hours, phone numbers and directions for Ashes Denton and Lewisville.','''<section class="page-heading mint"><span class="eyebrow">DENTON & OLD TOWN LEWISVILLE</span><h1>Locations & hours</h1><p>Choose your shop. Call ahead or get directions in one click.</p></section><section class="section compact-top" id="contact">'''+shops(2)+'''</section>'''+faq(),'locations')
for i,s in enumerate(stores,1):
 other=next(x for x in stores if x!=s)
