page('explore.html','Products & Categories','Browse hemp and CBD, vapes, glass, pipes, rolling papers, grinders, hookah, kratom, scents and merchandise.','''<section class="page-heading lavender"><span class="eyebrow">THE ASHES PRODUCT GUIDE</span><h1>Products</h1><p>Choose a category below. Call either shop to check today’s selection.</p><a class="text-link" href="contact.html">Phone numbers & contact →</a></section><div class="product-directory">'''+product_index+'<div class="product-groups">'+product_sections+'''<p class="small-note">Categories reflect Ashes’s published store pages. This guide is not a live stock list or online checkout. Ask your shop about specific items.</p></div></div>''','products')
page('contact.html','Contact Ashes','Call Ashes in Denton or Lewisville to check today’s product selection, hours or directions.','''<section class="page-heading peach"><span class="eyebrow">TALK TO YOUR LOCAL SHOP</span><h1>Contact Ashes</h1><p>For product availability, shop questions or special hours, call the location you plan to visit.</p></section><section class="section compact-top">'''+shops(2)+'''<div class="social-contact"><div><h2>Follow the shops</h2><p>Find current shop updates and event posts on social media.</p></div><div><a class="button outline" href="https://www.instagram.com/ashes.tx/" target="_blank" rel="noopener">Instagram ↗</a><a class="text-link" href="https://www.facebook.com/ashesdenton/" target="_blank" rel="noopener">Denton Facebook ↗</a><a class="text-link" href="https://www.facebook.com/asheslewisville/" target="_blank" rel="noopener">Lewisville Facebook ↗</a></div></div></section>''','contact')
page('story.html','About Ashes','Independent smoke shops in Denton since 2014 and Old Town Lewisville since 2023.','''<section class="page-heading yellow"><span class="eyebrow">INDEPENDENT SPIRIT. NORTH TEXAS ROOTS.</span><h1>About Ashes</h1><p>A neighborhood smoke shop with room to be yourself.</p></section><section class="about-story section"><div><h2>Good people.<br>No pressure.</h2><p>Look around, ask questions and take your time. Ashes staff don’t work on commission.</p><p>Hemp & CBD, vapes, papers, glass, grinders, hookah and more bring plenty to explore. The glass selection includes name-brand pieces and local artist work.</p><a class="button dark" href="explore.html">Explore products →</a></div><img src="assets/ashes-v4-hero.webp" alt="Original colorful Ashes skeleton-and-accessories illustration" width="1254" height="1254" loading="lazy"></section><section class="timeline section"><div><span class="year">2014</span><h2>Denton comes first.</h2><p>Ashes has served Denton from South Carroll Boulevard since 2014.</p><a class="text-link" href="denton.html">Denton store details →</a></div><div><span class="year">2023</span><h2>Hello, Old Town.</h2><p>The Old Town Lewisville location has been open on West Main Street since 2023.</p><a class="text-link" href="lewisville.html">Lewisville store details →</a></div></section>'''+event()+'''<section class="archive-teaser section"><figure><img src="assets/craft-p225.webp" alt="Glassmaking at a Denton event in April 2018" width="1800" height="1200" loading="lazy"><figcaption>Denton archive · April 20, 2018</figcaption></figure><div><span class="eyebrow">PHOTOS & HISTORY</span><h2>From the archive</h2><p>Glass artists, festival moments and a look back at the shop’s history.</p><a class="button outline" href="archive.html">View photo archive →</a><p class="small-note">Archive photos show past events, rather than current inventory or upcoming activities.</p></div></section>''','about')
gallery=''.join(f'<button class="gallery-item" data-full="assets/{p["file"]}" data-caption="{e(p["alt"])}" aria-label="Enlarge gallery photo {i}"><img src="assets/{p["file"]}" alt="{e(p["alt"])}" loading="lazy" width="1200" height="1000"><span>{i:02} / ENLARGE ↗</span></button>' for i,p in enumerate(photos,1))
page('archive.html','The archive','A selection of glassmaking photographs and festival material from Ashes’s original website.','''<section class="page-intro archive-intro"><span class="eyebrow">DENTON / PHOTOS & HISTORY</span><h1>Photo archive</h1><p>A little history, in good hands.</p></section><section class="section archive-gallery"><p class="archive-notice">These selected photographs carry April 20, 2018 capture dates in their image metadata. They show a past Denton event, not current staff, inventory or an upcoming event. Credits follow each file’s metadata.</p><div class="gallery-grid">'''+gallery+'''</div><a class="text-link" href="https://www.ashestx.com/home" target="_blank" rel="noopener">Explore the complete original gallery ↗</a></section><section class="section archive-event"><div class="section-head"><span class="eyebrow">PRESERVED FESTIVAL MATERIAL</span><h2>The music.<br>The makers.</h2><p>The original lineup has no confirmed event date.<br>It is preserved here as historical material.</p></div><div class="archive-columns"><div><h3>Band lineup</h3><dl class="lineup">'''+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in lineup)+'''</dl></div><div><h3>Artists & entertainment</h3><p><b>Artists</b><br>Sean Dietrich · Alex Denham</p><p><b>Glass blowers</b><br>The Gurk Monster · 8MM Glass<br>Nic Ric Glass · Z-Pot Glass</p><p><b>Comedians</b><br>Listed as “TBA” on the original page.</p><p>The original event graphics and four sponsor boards remain in the <a class="inline-link" href="https://www.ashestx.com/home" target="_blank" rel="noopener">source collection ↗</a>.</p></div></div><p class="small-note">These materials do not establish an upcoming festival or an ongoing sponsorship. The original website credits JC Extraordinaire. The complete source audit is preserved with the design package.</p></section><dialog id="gallery-dialog"><button class="close-dialog" aria-label="Close image">×</button><img alt=""><p></p><div class="lightbox-controls"><button id="gallery-prev" aria-label="Previous image">←</button><span id="gallery-position"></span><button id="gallery-next" aria-label="Next image">→</button></div></dialog>''','about')
